{
  "$schema": "https://opencode.ai/tui.json",
  "theme": "subway-seat"
}

$dark = $true
if ($IsMacOS) { $dark = (defaults read -g AppleInterfaceStyle 2>$null) -eq 'Dark' }
elseif ($IsWindows -or $PSVersionTable.PSEdition -eq 'Desktop') {
    $dark = (Get-ItemPropertyValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' AppsUseLightTheme -ErrorAction Ignore) -ne 1
}
. "$PSScriptRoot/$(if ($dark) { 'subway-seat' } else { 'subway-seat-enamel' }).ps1"

Alfred keeps one theme for macOS Light mode and one for Dark mode:
with macOS in Light mode, pick Subway Seat Enamel;
switch macOS to Dark mode, then pick Subway Seat (or Subway Seat Tunnel).

Telegram keeps one theme for day and one for Night Mode (main menu › Night Mode):
with Night Mode off, open subway-seat-enamel.tdesktop-theme;
with Night Mode on, open subway-seat.tdesktop-theme (or subway-seat-tunnel);
then click Settings › Chat Settings › Auto-night mode until it reads System.

@import url("subway-seat-enamel.css");
@media (prefers-color-scheme: dark) {
  @import url("subway-seat.css");
}

walnut.code:
@import "subway-seat.css";

window#waybar { background: @mantle; color: @text; border-bottom: 1px solid @crust; }
#workspaces button { color: @subtext0; }
#workspaces button:hover { background: @hover; }
#workspaces button.active, #workspaces button.focused { color: @text_hi; box-shadow: inset 0 -2px @yellow; }
#workspaces button.urgent { color: @orange; }
#battery.warning { color: @yellow; }
#battery.critical { color: @orange; }

